from __future__ import annotations

import asyncio
from types import SimpleNamespace

import httpx2
import pytest
from ds import settings as settings_module
from ds.ai import model
from ds.settings import ApiKey
from ds.util.const import DEFAULT_AI_MODEL
from ds.util.logging import log_call
from pydantic_ai.models.github_copilot import GitHubCopilotModel
from pydantic_ai.models.openai import OpenAIResponsesModel

GATEWAY = "gateway/anthropic:claude-haiku-5-5"
STORE = "(run `ds settings sync`)"


def _stored(monkeypatch: pytest.MonkeyPatch, **keys: str | None) -> None:
    """What ds.settings holds, as ds.ai.model reads it: only the keys named are stored."""
    names = ("github_copilot_token", "pydantic_project_api_key")
    held = {name: ApiKey(keys[name]) if keys.get(name) else None for name in names}
    monkeypatch.setattr(model, "get_settings", lambda: SimpleNamespace(**held))


def test_the_default_model_builds_with_nothing_stored(monkeypatch: pytest.MonkeyPatch) -> None:
    _stored(monkeypatch)
    assert model.ai_model() is not None  # as at import, on a machine with no token or key


def test_a_gateway_setting_is_passed_through_as_written() -> None:
    assert model.ai_model(GATEWAY) == GATEWAY


@pytest.mark.parametrize(
    ("setting", "kind"),
    [
        ("github-copilot:gpt-5.6-luna", OpenAIResponsesModel),  # GPT ids: the Responses endpoint only
        ("github-copilot:gpt-6-luna", OpenAIResponsesModel),
        ("github-copilot:claude-haiku-4.5", GitHubCopilotModel),  # the rest: chat completions
        ("github-copilot:gemini-3.8-flash", GitHubCopilotModel),
    ],
)
def test_a_copilot_id_gets_the_endpoint_copilot_serves_it_on(
    monkeypatch: pytest.MonkeyPatch, setting: str, kind: type
) -> None:
    _stored(monkeypatch)  # no token: building must not need one
    built = model.ai_model(setting)
    assert type(built) is kind
    assert built.model_name == setting.partition(":")[2]
    assert str(built.client.base_url).startswith("https://api.githubcopilot.com")
    assert built.client.default_headers["copilot-integration-id"]  # the provider's own client headers


def test_the_copilot_token_is_read_when_asked_not_when_built(monkeypatch: pytest.MonkeyPatch) -> None:
    _stored(monkeypatch)
    model.ai_model("github-copilot:gpt-5.6-luna")
    with pytest.raises(model.CopilotTokenMissingError, match="no GitHub Copilot token is stored"):
        model._copilot_token()  # what the client calls for every request
    _stored(monkeypatch, github_copilot_token="gho_stored_later")  # noqa: S106  # not a real token
    assert model._copilot_token() == "gho_stored_later"


def test_each_provider_names_what_is_missing(monkeypatch: pytest.MonkeyPatch) -> None:
    _stored(monkeypatch)
    assert model.credential_problem("github-copilot:gpt-5.6-luna") == f"no GitHub Copilot token is stored {STORE}"
    assert model.credential_problem(GATEWAY) == f"no AI key is stored {STORE}"
    assert model.credential_problem("test") == ""  # a model that needs nothing stored
    # the other provider's secret doesn't count
    _stored(monkeypatch, pydantic_project_api_key="pylf_key")
    assert model.credential_problem("github-copilot:gpt-5.6-luna") != ""
    assert model.credential_problem(GATEWAY) == ""
    _stored(monkeypatch, github_copilot_token="gho_token")  # noqa: S106  # not a real token
    assert model.credential_problem("github-copilot:gpt-5.6-luna") == ""


def test_spend_is_tracked_only_through_the_gateway() -> None:
    assert model.spend_tracked(GATEWAY) is True
    assert model.spend_tracked("github-copilot:gpt-5.6-luna") is False


def test_the_label_is_the_model_alone() -> None:
    assert model.model_label("github-copilot:gpt-5.6-luna") == "gpt-5.6-luna"
    assert model.model_label(GATEWAY) == "claude-haiku-5-5"
    assert model.model_label(DEFAULT_AI_MODEL)


def test_an_exported_copilot_token_wins_over_the_keyring(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(
        settings_module, "_stored", lambda name: "gho_keyring" if name == "GITHUB_COPILOT_TOKEN" else None
    )
    monkeypatch.delenv("GITHUB_COPILOT_API_KEY", raising=False)
    assert settings_module.init_settings().github_copilot_token.get_secret_value() == "gho_keyring"
    monkeypatch.setenv("GITHUB_COPILOT_API_KEY", "gho_exported")
    assert settings_module.init_settings().github_copilot_token.get_secret_value() == "gho_exported"


class _Body(httpx2.AsyncByteStream):
    def __init__(self, chunks: list[bytes]) -> None:
        self.chunks = chunks

    async def __aiter__(self):
        for chunk in self.chunks:
            yield chunk


def _answer(chunks: list[bytes], **headers: str) -> httpx2.Response:
    return httpx2.Response(200, headers=headers, stream=_Body(chunks))


async def _noted(response: httpx2.Response) -> bytes:
    await model._note_seat_use(response)  # the client's response hook
    return await response.aread()


def test_a_copilot_answers_quota_headers_land_on_the_running_call() -> None:
    quota = {"x-quota-snapshot-premium_interactions": "ent=300&rem=75.0"}
    with log_call("agent", "test") as call:
        asyncio.run(_noted(_answer([b"{}"], **quota, **{"x-request-id": "1"})))
    assert call[model.SEAT_QUOTA_FIELD] == quota
    assert model.SEAT_CREDITS_FIELD not in call  # the body named no cost
    asyncio.run(_noted(_answer([b"{}"], **quota)))  # outside a call: nothing kept, no error


def test_what_each_answer_cost_is_summed_on_the_call_and_the_body_is_untouched() -> None:
    # a streamed answer's last event, cut inside the figure, then a second request of the run
    chunks = [b'data: {"copilot_usage": {"total_nano_', b'aiu": 45000', b'00000}, "type": "response.completed"}']
    with log_call("agent", "test") as call:
        body = asyncio.run(_noted(_answer(chunks)))
        asyncio.run(_noted(_answer([b'{"copilot_usage":{"total_nano_aiu":500000000}}'])))
    assert body == b"".join(chunks)
    assert call[model.SEAT_CREDITS_FIELD] == pytest.approx(5.0)


def test_a_compressed_or_failed_answer_is_left_alone() -> None:
    with log_call("agent", "test") as call:
        packed = _answer([b"x"], **{"content-encoding": "gzip"})
        asyncio.run(model._note_seat_use(packed))
        refused = httpx2.Response(403, stream=_Body([b'{"total_nano_aiu": 1}']))
        asyncio.run(_noted(refused))
    assert isinstance(packed.stream, _Body)
    assert model.SEAT_CREDITS_FIELD not in call


def test_the_copilot_client_notes_the_seats_use_of_every_answer() -> None:
    built = model.ai_model("github-copilot:gpt-5.6-luna")
    hooks = built.client._client.event_hooks["response"]  # where _copilot_model adds it
    assert model._note_seat_use in hooks


